			<label class="font-semibold">Regione<select required class="mt-1 w-full rounded-lg border p-3" name="regione_id" id="create-event-region"><option value="">Seleziona regione</option><?php foreach ($regions as $region): ?><option value="<?php echo (int) $region['id']; ?>"><?php echo htmlspecialchars($region['nome']); ?></option><?php endforeach; ?></select></label>
			<label class="font-semibold">Provincia<select required class="mt-1 w-full rounded-lg border p-3" name="provincia_id" id="create-event-province"><option value="">Seleziona provincia</option></select></label>
			<label class="font-semibold">Comune<select required class="mt-1 w-full rounded-lg border p-3" name="comune_id" id="create-event-municipality"><option value="">Seleziona comune</option></select></label>
