		<div class="flex flex-wrap gap-6"><label><input type="checkbox" name="is_paid" value="1"> Evento a pagamento</label><label><input type="checkbox" name="has_cosplay_contest" value="1"> Contest cosplay</label></div>
		<section class="rounded-xl border border-slate-200 p-4"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-lg font-bold">Ospiti evento</h2><button type="button" id="create-event-new-guest" class="rounded-lg bg-blue-600 px-3 py-2 text-sm font-semibold text-white">+ Nuovo ospite</button></div><div class="relative mt-3"><input id="create-event-guest-search" type="search" autocomplete="off" placeholder="Cerca ospite..." class="w-full rounded-lg border p-3"><div id="create-event-guest-results" class="absolute z-10 hidden max-h-60 w-full overflow-auto rounded-lg border bg-white shadow"></div></div><div id="create-event-selected-guests" class="mt-4 flex flex-wrap gap-2"></div></section>
		<div class="flex justify-end"><button class="rounded-lg bg-green-700 px-5 py-3 font-bold text-white" type="submit">Crea edizione</button></div>
