<script src="/public_assets/js/wysiwyg-editor.js"></script>
<script>
document.addEventListener('DOMContentLoaded', function () {
	WysiwygEditor.init('#create-event-description', { content: '', name: 'descrizione', placeholder: "Scrivi la descrizione dell'edizione..." });
	const region = document.getElementById('create-event-region'), province = document.getElementById('create-event-province'), municipality = document.getElementById('create-event-municipality');
	region.addEventListener('change', async function () { province.innerHTML = '<option value="">Caricamento province...</option>'; municipality.innerHTML = '<option value="">Seleziona comune</option>'; const rows = await (await fetch('/api/province/' + encodeURIComponent(region.value))).json(); province.innerHTML = '<option value="">Seleziona provincia</option>'; rows.forEach(row => province.insertAdjacentHTML('beforeend', '<option value="' + Number(row.id) + '">' + String(row.nome).replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</option>')); });
	province.addEventListener('change', async function () { municipality.innerHTML = '<option value="">Caricamento comuni...</option>'; const rows = await (await fetch('/api/comuni/' + encodeURIComponent(province.value))).json(); municipality.innerHTML = '<option value="">Seleziona comune</option>'; rows.forEach(row => municipality.insertAdjacentHTML('beforeend', '<option value="' + Number(row.id) + '">' + String(row.nome).replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</option>')); });
	const form = document.querySelector('form'), feedback = document.getElementById('dashboard-event-create-feedback');
	let selectedGuests = [];
	const guestSearch = document.getElementById('create-event-guest-search');
	const guestResults = document.getElementById('create-event-guest-results');
	const guestBox = document.getElementById('create-event-selected-guests');
	const guestIds = document.getElementById('create-event-guest-ids');
	function renderGuests() { guestBox.innerHTML = ''; selectedGuests.forEach(function (guest) { const item = document.createElement('span'); item.className = 'inline-flex items-center gap-2 rounded-full bg-blue-100 px-3 py-1 text-sm text-blue-800'; item.textContent = guest.name; const remove = document.createElement('button'); remove.type = 'button'; remove.textContent = '×'; remove.className = 'font-bold'; remove.addEventListener('click', function () { selectedGuests = selectedGuests.filter(function (row) { return Number(row.id) !== Number(guest.id); }); renderGuests(); }); item.appendChild(remove); guestBox.appendChild(item); }); guestIds.value = JSON.stringify(selectedGuests.map(function (guest) { return Number(guest.id); })); }
	let guestTimer;
	guestSearch.addEventListener('input', function () { clearTimeout(guestTimer); guestResults.innerHTML = ''; guestResults.classList.add('hidden'); if (guestSearch.value.trim().length < 2) return; guestTimer = setTimeout(async function () { const response = await fetch('/dashboard/guests/search?q=' + encodeURIComponent(guestSearch.value.trim()), { headers: { Accept: 'application/json' } }); const payload = await response.json(); guestResults.classList.remove('hidden'); (payload.guests || []).forEach(function (guest) { const option = document.createElement('button'); option.type = 'button'; option.className = 'block w-full px-3 py-2 text-left hover:bg-slate-50'; option.textContent = guest.name; option.addEventListener('click', function () { if (!selectedGuests.some(function (row) { return Number(row.id) === Number(guest.id); })) selectedGuests.push(guest); renderGuests(); guestSearch.value = ''; guestResults.classList.add('hidden'); }); guestResults.appendChild(option); }); }, 250); });
	document.getElementById('create-event-new-guest').addEventListener('click', async function () { const name = window.prompt('Nome del nuovo guest:'); if (!name || name.trim().length < 2) return; const body = new FormData(); body.append('name', name.trim()); body.append('csrf_token', '<?php echo htmlspecialchars($_SESSION['csrf_token'] ?? '', ENT_QUOTES); ?>'); const response = await fetch('/dashboard/guests/create', { method: 'POST', body: body, headers: { Accept: 'application/json' } }); const payload = await response.json(); if (!response.ok || !payload.success) { window.alert(payload.message || 'Guest non creato.'); return; } selectedGuests.push(payload.guest); renderGuests(); });
	renderGuests();
	form.addEventListener('submit', async function (event) { event.preventDefault(); const button = form.querySelector('button[type="submit"]'); button.disabled = true; try { const response = await fetch(form.action, { method: 'POST', body: new FormData(form), headers: { Accept: 'application/json' } }); const result = await response.json(); if (!response.ok || !result.success) throw new Error(result.message || 'Creazione non riuscita.'); feedback.textContent = result.message; feedback.className = 'mt-4 rounded-lg border border-green-200 bg-green-50 p-4 text-sm text-green-800'; form.reset(); } catch (error) { feedback.textContent = error.message || 'Creazione non riuscita.'; feedback.className = 'mt-4 rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-800'; } finally { button.disabled = false; } });
});
</script>
